//! Prover-side oracle state carried between phases.

use alloc::boxed::Box;
use alloc::vec::Vec;
use core::any::Any;
use core::marker::PhantomData;

use p3_commit::Mmcs;
use p3_field::{ExtensionField, TwoAdicField};
use p3_matrix::dense::DenseMatrix;
use p3_matrix::extension::FlatMatrixView;
use p3_multilinear_util::poly::Poly;

/// The first message is either ordinary host data or a native-oracle handle
/// represented only by its exact length. The committer owns the resident
/// buffer; no device identifier enters the proof engine or transcript.
pub enum HidingWhirInitialMessage<F> {
    Host(Poly<F>),
    Resident { len: usize },
}

impl<F> HidingWhirInitialMessage<F> {
    pub(super) fn borrowed(&self) -> ZkWhirInitialMessage<'_, F> {
        match self {
            Self::Host(message) => ZkWhirInitialMessage::Host(message.as_slice()),
            Self::Resident { len } => ZkWhirInitialMessage::Resident { len: *len },
        }
    }

    pub fn host(&self) -> Option<&Poly<F>> {
        match self {
            Self::Host(message) => Some(message),
            Self::Resident { .. } => None,
        }
    }
}

#[derive(Clone, Copy)]
pub enum ZkWhirInitialMessage<'a, F> {
    Host(&'a [F]),
    Resident { len: usize },
}

impl<'a, F> ZkWhirInitialMessage<'a, F> {
    pub fn len(self) -> usize {
        match self {
            Self::Host(message) => message.len(),
            Self::Resident { len } => len,
        }
    }

    pub fn host(self) -> Option<&'a [F]> {
        match self {
            Self::Host(message) => Some(message),
            Self::Resident { .. } => None,
        }
    }
}

/// Prover-side handoff between the commit and open phases.
pub struct HidingWhirProverData<F, EF, MT>
where
    F: TwoAdicField,
    EF: ExtensionField<F>,
    MT: Mmcs<F>,
{
    /// Committed multilinear evaluations.
    pub message: HidingWhirInitialMessage<F>,
    /// Limb-major ZK encoding randomness of the initial oracle.
    pub randomness: Vec<F>,
    /// Merkle prover data behind the initial commitment.
    pub merkle: MT::ProverData<DenseMatrix<F>>,
    /// Marker tying the data to its extension field.
    pub(crate) _marker: PhantomData<EF>,
}

/// Opaque ownership token for a committed oracle regenerated by a native prover.
/// It is prover-local and never enters a proof or transcript.
pub struct ZkWhirReplayHandle(Box<dyn Any + Send + Sync>);

impl ZkWhirReplayHandle {
    #[doc(hidden)]
    pub fn new<T: Any + Send + Sync>(value: T) -> Self {
        Self(Box::new(value))
    }

    #[doc(hidden)]
    pub fn downcast_ref<T: Any>(&self) -> Option<&T> {
        self.0.downcast_ref()
    }

    #[doc(hidden)]
    pub fn downcast<T: Any>(self) -> Result<Box<T>, Self> {
        self.0.downcast().map_err(Self)
    }
}

/// Merkle prover data of the active committed oracle.
pub(super) enum ZkRoundData<'a, F, EF, MT>
where
    F: TwoAdicField,
    EF: ExtensionField<F>,
    MT: Mmcs<F>,
{
    /// Base-field initial oracle.
    Base(MT::ProverData<DenseMatrix<F>>),
    /// Immutable initial oracle kept by the caller across bounded exposures.
    RetainedBase(&'a MT::ProverData<DenseMatrix<F>>),
    /// Extension-field folded oracle.
    Ext(<MT as Mmcs<F>>::ProverData<FlatMatrixView<F, EF, DenseMatrix<EF>>>),
    /// Native oracle represented only by a private regeneration handle.
    Replay(ZkWhirReplayHandle),
}
